        <div class="option-row"><input class="input" type="text" value="Earth"><span class="checkbox"><input type="checkbox"> Correct</span><span class="btn btn--danger btn--icon">✕</span></div>
        <div class="option-row"><input class="input" type="text" placeholder="Option text"><span class="checkbox"><input type="checkbox"> Correct</span><span class="btn btn--danger btn--icon">✕</span></div>
      </div>
      <div class="buttons" style="margin-bottom: 28px"><span class="btn btn--ghost btn--sm">+ Add option</span></div>

      <div class="field">
        <span class="checkbox"><input type="checkbox" checked> Active</span>
        <span class="field-hint">Only active questions are played.</span>
      </div>

      <!-- Layer: Error state (shown when a rule fails) -->
      <div class="errors">Mark at least one option as correct</div>

      <div class="buttons">
        <span class="btn btn--pink">Save question</span>
        <span class="btn btn--ghost">Cancel</span>
      </div>
    </div>
  </main>
</body>
</html>
